434	void SpectrumAnalyzer::fromJSON(nlohmann::json j)
435	{
436	    if(j.is_null()) {
437	        return;
438	    }
439	    if(j.contains("traces")) {
440	        traceModel.fromJSON(j["traces"]);
441	    }
442	    if(j.contains("tiles")) {
443	        tiles->fromJSON(j["tiles"]);
444	    }
445	    if(j.contains("markers")) {
446	        markerModel->fromJSON(j["markers"]);
447	    }
448	    if(j.contains("sweep")) {
449	        // restore sweep settings
450	        auto sweep = j["sweep"];
451	        if(sweep.contains("frequency")) {
452	            auto freq = sweep["frequency"];
453	            SetStartFreq(freq.value("start", settings.freqStart));
454	            SetStopFreq(freq.value("stop", settings.freqStop));
455	        }
456	        if(sweep.contains("acquisition")) {
457	            auto acq = sweep["acquisition"];
458	            SetRBW(acq.value("RBW", settings.RBW));
459	            auto w = WindowFromString(QString::fromStdString(acq.value("window", "")));
460	            if(w == DeviceDriver::SASettings::Window::Last) {
461	                // invalid, keep current value
462	                w = (DeviceDriver::SASettings::Window) settings.window;
463	            }
464	            SetWindow(w);
465	            auto d = DetectorFromString(QString::fromStdString(acq.value("detector", "")));
466	            if(d == DeviceDriver::SASettings::Detector::Last) {
467	                // invalid, keep current value
468	                d = (DeviceDriver::SASettings::Detector) settings.detector;
469	            }
470	            SetDetector(d);
471	        }
472	        if(sweep.contains("trackingGenerator")) {
473	            auto tracking = sweep["trackingGenerator"];
474	            SetTGEnabled(tracking.value("enabled", settings.trackingGenerator ? true : false));
475	            int port = tracking.value("port", 1);
476	            SetTGPort(port);
477	            SetTGLevel(tracking.value("power", settings.trackingPower));
478	            SetTGOffset(tracking.value("offset", settings.trackingOffset));
479	        }
480	        if(sweep.contains("normalization")) {
481	            auto norm = sweep["normalization"];
482	            // restore normalization data
483	            normalize.portCorrection.clear();
484	            if(norm.contains("corrections")) {
485	                for(auto& el : norm["corrections"].items()) {
486	                    normalize.portCorrection[QString::fromStdString(el.key())] = {};
487	                    for(auto p : el.value()) {
488	                        normalize.portCorrection[QString::fromStdString(el.key())].push_back(p);
489	                    }
490	                }
491	            }
492	            normalize.f_start = norm.value("start", normalize.f_start);
493	            normalize.f_stop = norm.value("stop", normalize.f_stop);
494	            normalize.points = norm.value("points", normalize.points);
495	            normalize.Level->setValue(norm.value("level", normalize.Level->value()));
496	            // check correction vector size
497	            bool correctSize = true;
498	            for(auto c : normalize.portCorrection) {
499	                if(c.second.size() != normalize.points) {
500	                    correctSize = false;
501	                    break;
502	                }
503	            }
504	            EnableNormalization(correctSize);
505	        }
506	        SetSingleSweep(sweep.value("single", singleSweep));
507	        SetAveraging(sweep.value("averages", averages));
508	    }
509	}
