513	void SpectrumAnalyzer::NewDatapoint(DeviceDriver::SAMeasurement m)
514	{   
515	    if(isActive != true) {
516	        return;
517	    }
518	
519	    if(changingSettings) {
520	        // already setting new sweep settings, ignore incoming points from old settings
521	        return;
522	    }
523	
524	    if(singleSweep && average.getLevel() == averages) {
525	        Stop();
526	        return;
527	    }
528	
529	    auto m_avg = average.process(m);
530	    if(average.settled()) {
531	        setOperationPending(false);
532	    }
533	
534	    if(settings.freqStart == settings.freqStop) {
535	        // keep track of first point time
536	        if(m_avg.pointNum == 0) {
537	            firstPointTime = m_avg.us;
538	            m_avg.us = 0;
539	        } else {
540	            m_avg.us -= firstPointTime;
541	        }
542	    }
543	
544	    window->addStreamingData(m_avg, AppWindow::SADataType::Raw, settings.freqStart == settings.freqStop);
545	
546	    if(normalize.measuring) {
547	        if(average.currentSweep() == averages) {
548	            // this is the last averaging sweep, use values for normalization
549	            if(normalize.portCorrection.size() > 0 || m_avg.pointNum == 0) {
550	                // add measurement
551	                for(auto m : m_avg.measurements) {
552	                    normalize.portCorrection[m.first].push_back(m.second);
553	                }
554	                if(m_avg.pointNum == DeviceDriver::SApoints() - 1) {
555	                    // this was the last point
556	                    normalize.measuring = false;
557	                    normalize.f_start = settings.freqStart;
558	                    normalize.f_stop = settings.freqStop;
559	                    normalize.points = DeviceDriver::SApoints();
560	                    EnableNormalization(true);
561	                    qDebug() << "Normalization measurement complete";
562	                }
563	            }
564	        }
565	        int percentage = (((average.currentSweep() - 1) * 100) + (m_avg.pointNum + 1) * 100 / DeviceDriver::SApoints()) / averages;
566	        if(window->showGUI()) {
567	            normalize.dialog.setValue(percentage);
568	        }
569	    }
570	
571	    if(normalize.active) {
572	        double corr = pow(10.0, normalize.Level->value() / 20.0);
573	        for(auto &m : m_avg.measurements) {
574	            m.second /= normalize.portCorrection[m.first][m_avg.pointNum];
575	            m.second *= corr;
576	        }
577	        window->addStreamingData(m_avg, AppWindow::SADataType::Normalized, settings.freqStart == settings.freqStop);
578	    }
579	
580	
581	    traceModel.addSAData(m_avg, settings);
582	    emit dataChanged();
583	    if(m_avg.pointNum == DeviceDriver::SApoints() - 1) {
584	        UpdateAverageCount();
585	        markerModel->updateMarkers();
586	    }
587	    static unsigned int lastPoint = 0;
588	    if(m_avg.pointNum > 0 && m_avg.pointNum != lastPoint + 1) {
589	        qWarning() << "Got point" << m_avg.pointNum << "but last received point was" << lastPoint << "("<<(m_avg.pointNum-lastPoint-1)<<"missed points)";
590	    }
591	    lastPoint = m_avg.pointNum;
592	
593	    lastFreq = m_avg.frequency;
594	    lastTime = (double) m_avg.us / 1000000;
595	}
