628	void SpectrumAnalyzer::SetCenterFreq(double freq)
629	{
630	    auto old_span = settings.freqStop - settings.freqStart;
631	    if (freq - old_span / 2 <= DeviceDriver::getInfo(window->getDevice()).Limits.SA.minFreq) {
632	        // would shift start frequency below minimum
633	        settings.freqStart = 0;
634	        settings.freqStop = 2 * freq;
635	    } else if(freq + old_span / 2 >= DeviceDriver::getInfo(window->getDevice()).Limits.SA.maxFreq) {
636	        // would shift stop frequency above maximum
637	        settings.freqStart = 2 * freq - DeviceDriver::getInfo(window->getDevice()).Limits.SA.maxFreq;
638	        settings.freqStop = DeviceDriver::getInfo(window->getDevice()).Limits.SA.maxFreq;
639	    } else {
640	        settings.freqStart = freq - old_span / 2;
641	        settings.freqStop = freq + old_span / 2;
642	    }
643	    ConstrainAndUpdateFrequencies();
644	}
