646	void SpectrumAnalyzer::SetSpan(double span)
647	{
648	    auto old_center = (settings.freqStart + settings.freqStop) / 2;
649	    if(old_center < DeviceDriver::getInfo(window->getDevice()).Limits.SA.minFreq + span / 2) {
650	        // would shift start frequency below minimum
651	        settings.freqStart = DeviceDriver::getInfo(window->getDevice()).Limits.SA.minFreq;
652	        settings.freqStop = DeviceDriver::getInfo(window->getDevice()).Limits.SA.minFreq + span;
653	    } else if(old_center > DeviceDriver::getInfo(window->getDevice()).Limits.SA.maxFreq - span / 2) {
654	        // would shift stop frequency above maximum
655	        settings.freqStart = DeviceDriver::getInfo(window->getDevice()).Limits.SA.maxFreq - span;
656	        settings.freqStop = DeviceDriver::getInfo(window->getDevice()).Limits.SA.maxFreq;
657	    } else {
658	        settings.freqStart = old_center - span / 2;
659	         settings.freqStop = settings.freqStart + span;
660	    }
661	    ConstrainAndUpdateFrequencies();
